export const BODY: string = "\n<p>تغيير حجم صورة عبر الإنترنت يستغرق نحو دقيقة بمجرد أن تعرف الخطوات: ارفع الصورة واختر الحجم وراجع المعاينة ونزّل النتيجة. دون برامج للتثبيت ودون حسابات للإنشاء.</p>\n<p>يمر هذا الدليل بالعملية في مغيّر حجم الصور، من أول رفع إلى التنزيل الأخير: يغطي وضعي الحجم وقفل نسبة العرض إلى الارتفاع والقوالب وضبط الجودة.</p>\n<p>في النهاية ستعرف كيف تختار حجمًا مستهدفًا لموقع أو منشور اجتماعي أو طباعة، وكيف تراجع النتيجة قبل استخدامها. وإذا أردت السياق أولًا، اقرأ <a href=\"/ar/blog/dalil-taghyir-hajm-as-suwar/\">دليل مغيّر حجم الصور الكامل</a>.</p>\n<h2 id=\"resize-in-six-steps\">تغيير الحجم في ست خطوات</h2>\n<p>العملية كلها تتبع نفس الخطوات الست في كل مرة: تعلمها مرة وكل تغيير حجم بعدها يصبح روتينيًا، سواء كانت صورة هاتف أو صورة منتج أو لقطة شاشة.</p>\n<ol>\n<li>ارفع صورتك: اسحب وأفلت ملف JPG أو PNG أو WebP أو HEIC أو GIF أو BMP أو SVG حتى 20 MB، أو تصفحه على جهازك، أو الصق لقطة شاشة بـCtrl+V.</li>\n<li>اختر وضع بالبكسلات أو بالنسبة المئوية: استخدم بالبكسلات لحجم دقيق حتى 12000 بكسل، أو بالنسبة المئوية للقياس بين 10 بالمئة و200 بالمئة.</li>\n<li>ثبّت الحجم: اكتب العرض والارتفاع أو اسحب منزلق النسبة المئوية أو المس زرًا سريعًا أو انقر قالبًا مثل منشور إنستغرام أو Full HD.</li>\n<li>راجع قفل النسبة والملاءمة: أبقِ خيار نسبة العرض إلى الارتفاع مقفلة مفعّلًا للقياس متناسبًا، أو افتحه واختر احتواء أو تغطية أو تمديد دقيق.</li>\n<li>اختر الصيغة والجودة: أبقِ الأصل أو بدّل إلى JPG أو PNG أو WebP، واضبط الجودة من 10 بالمئة إلى 100 بالمئة، واختر لون خلفية غير لامع لـJPG.</li>\n<li>غيّر الحجم ونزّل: انقر تغيير حجم الكل وراجع النتيجة في عرض المقارنة ثم نزّل الملف أو ZIP الدفعة.</li>\n</ol>\n<h2 id=\"choose-your-target-size\">اختر الحجم المستهدف أولًا</h2>\n<p>قرر الحجم قبل فتح الأداة، لا وأنت تنظر إلى مربع العرض: الوجهة تقرر الرقم: صورة مدونة ومنشور اجتماعي وطباعة تريد أبعادًا مختلفة.</p>\n<p>اسأل نفسك أين ستُرى الصورة وكم كبيرة ستظهر هناك: صورة تُعرض بعرض 800 بكسل تحتاج نحو 800 بكسل في الملف، مع قليل إضافي للشاشات الحادة. وعندما لا يُعطى لك حجم دقيق، استخدم الأحجام الشائعة كدليل: صور محتوى المدونة تعمل جيدًا بعرض 1200 بكسل، والمصغرات بـ600، والترويسات بملء الشاشة بأوسع.</p>\n<p>دوّن الهدف قبل رفع أي شيء: ملاحظة تقول 1080 في 1080 للمنشور و1200 عرضًا للمدونة تبقي العمل سريعًا وتمنع تغيير حجم نفس الصورة مرتين. والأداة تتذكر هدفك أثناء الجلسة.</p>\n<h2 id=\"pixels-or-percentage\">بالبكسلات أو بالنسبة المئوية: أي وضع تستخدم؟</h2>\n<p>استخدم بالبكسلات عندما تعطيك الوجهة رقمًا دقيقًا: المنصات الاجتماعية والأسواق وأدوات التصميم تنشر أحجامًا دقيقة، وكتابتها تضمن وصول الصورة بالحجم الصحيح.</p>\n<p>استخدم بالنسبة المئوية عندما يكون الهدف ببساطة أصغر: مجلد صور كاميرا بعرض 4000 بكسل لا يحتاج هدفًا دقيقًا، يحتاج أن يكون نصف حجمه. وتثبيت 50 بالمئة يقص كل صورة إلى النصف دون حساب. ويبقي وضع النسبة المئوية أيضًا الدفعات المتنوعة موحدة: كل صورة تقل بنفس النسبة، فتبقى الأحجام النسبية للمجموعة. وهذا يهم في معرض حيث يجب أن تبقى الصور متناسبة.</p>\n<h2 id=\"keep-the-aspect-ratio-locked\">أبقِ نسبة العرض إلى الارتفاع مقفلة</h2>\n<p>قفل نسبة العرض إلى الارتفاع هو أهم ضبط في الأداة: مع تفعيله، تغيير العرض يحدّث الارتفاع بنسبة دقيقة، فتحافظ الصورة على شكلها الطبيعي.</p>\n<p>عندما تسقط صورتك الأولى في قائمة فارغة، يثبت مغيّر الحجم العرض الأولي بحد أقصى 1200 بكسل ويحسب الارتفاع المناسب لك: تلك القيمة الأولية نقطة بداية، لا حكم. وافتح القفل فقط عندما تتطلب وجهة إطارًا دقيقًا بشكل مختلف: عند الفتح تظهر احتواء وتغطية وتمديد دقيق، ويجب أن تختار واحدًا عن قصد. ويحافظ احتواء على الصورة كاملة داخل الإطار، بينما تملأ تغطية الإطار بقص الحواف.</p>\n<h2 id=\"use-a-preset\">استخدم قالبًا عندما يناسب</h2>\n<p>القوالب هي أسرع طريق إلى حجم صحيح: نقرة واحدة تملأ الأبعاد الدقيقة لوجهة شائعة، فلا تكتب رقمًا أبدًا ولا تحتاج البحث عنه. إنها مثالية عندما تغيّر حجم صور كثيرة لنفس المنصة.</p>\n<p>عند النقر على قالب، تتبدل الأداة إلى وضع بالبكسلات وتملأ تلك الأبعاد: ما زلت تستطيع ضبطها بعدها، فالقالب نقطة بداية لا اختيار نهائي. ولا تغيّر القوالب شكل صورتك وحدها.</p>\n<p>صورة عريضة مغيّرة الحجم إلى قالب مربع مع قفل النسبة ستحافظ على شكلها العريض بعرض القالب، لا تصبح مربعة: لفرض الإطار المربع، افتح القفل واختر تغطية، أو قص الصورة أولًا بـ<a href=\"/ar/qass-as-suwar/\">قاص الصور</a>.</p>\n<ul>\n<li>منشور إنستغرام: 1080 في 1080، حجم خلاصة مربع.</li>\n<li>قصة إنستغرام: 1080 في 1920، حجم عمودي بملء الشاشة.</li>\n<li>مصغرة يوتيوب: 1280 في 720، حجم مصغرة عريض.</li>\n<li>غلاف فيسبوك: 851 في 315، حجم ترويسة عريض وقصير.</li>\n<li>ترويسة X: 1500 في 500، حجم لافتة عريض جدًا.</li>\n<li>Full HD: 1920 في 1080، حجم شاشة عريضة قياسي.</li>\n</ul>\n<h2 id=\"set-format-and-quality\">ثبّت الصيغة والجودة</h2>\n<p>تقرر الصيغة والجودة كيف يُحفظ الملف المغيّر الحجم، وهما مهمتان مثل الأبعاد: إبقاء الصيغة الأصلية هو الخيار الحكيم: تحتفظ الصورة المغيّرة الحجم بصيغتها، فلا مفاجآت.</p>\n<p>تغيير الصيغة في نفس التمريرة يوفر عملًا ثانيًا: لقطة PNG تستطيع أن تصبح JPG بجودة 85 بالمئة لمدونة، أو صورة JPG تستطيع أن تصبح WebP لصفحة ويب. وجودة قرب 85 بالمئة هي النقطة المثالية لمعظم صور الويب.</p>\n<p>تبقي الحواف حادة والتدرجات نظيفة بينما تقلل حجم الملف كثيرًا: اخفض الجودة نحو 65 بالمئة أو 75 بالمئة فقط عندما يجب أن يكون الملف صغيرًا جدًا، وارفعها نحو 90 بالمئة أو 95 بالمئة للصور التي ستُطبع أو تُعرض كبيرة.</p>\n<p>وإذا اخترت JPG كمخرج لـPNG شفاف، اختر أولًا لون الخلفية غير اللامع: تُملأ المناطق الشفافة بذلك اللون، الأبيض افتراضيًا، لأن JPG لا يستطيع حفظ الشفافية.</p>\n<h2 id=\"check-the-result\">راجع النتيجة قبل التنزيل</h2>\n<p>راجع دائمًا الصورة المغيّرة الحجم قبل استخدامها: انقر قارن على أي بطاقة نتيجة منتهية، أو انقر مصغرتها، لفتح مقارنة قبل وبعد. واعرض الأصل والمغيّر الحجم جنبًا إلى جنب بالحجم الكامل.</p>\n<p>انظر إلى النص أولًا، لأن النص يُظهر النعومة قبل أي شيء: ثم انظر إلى الوجوه والحواف، حيث يظهر التمديد أو التقليل المفرط أسهل. وإذا بدت الصورة ناعمة، فالجودة منخفضة جدًا أو الأصل صغير جدًا: أعد تغيير الحجم بجودة أعلى أو من أصل أكبر. وراجع أيضًا الأبعاد على بطاقة النتيجة، إضافة إلى الصورة نفسها.</p>\n<p>خطأ طباعي في مربع العرض سهل الارتكاب وسهل تفويته، وبطاقة النتيجة تُظهر حجم الإخراج الدقيق: تأكيد الأرقام يستغرق ثانيتين ويمنع إعادة رفع.</p>\n<h2 id=\"resize-a-batch\">غيّر حجم دفعة في تمريرة واحدة</h2>\n<p>صورة واحدة سريعة، لكن مجلد صور هو حيث يُظهر مغيّر الحجم عبر الإنترنت قيمته: أسقط صورًا عدة في القائمة وثبّت حجمًا وانقر تغيير حجم الكل وكل صورة تُعالج بنفس الضبط.</p>\n<p>مع قفل نسبة العرض إلى الارتفاع، تحافظ كل صورة على نسبها الخاصة بينما تشترك في حد العرض: تبقى الصور الشخصية عمودية والمشاهد أفقية، وهو ما تريده. وعند انتهاء صورتين أو أكثر، يظهر شريط دفعة جاهزة بزر تنزيل الكل (ZIP): نقرة واحدة تحزم كل ملف مغيّر الحجم في resized_images_compressmypic.zip، أسرع بكثير من تنزيل الملفات واحدًا واحدًا.</p>\n<p>ولدفعات أكبر، استخدم <a href=\"/ar/taghyir-hajm-jumli-lis-suwar/\">مغيّر حجم الصور بالدفعة</a>: نفس الضبط عبر مجلد كامل، مع تقرير واحد للمراجعة.</p>\n<h2 id=\"resize-on-your-phone\">غيّر الحجم من هاتفك</h2>\n<p>يعمل مغيّر الحجم على الهواتف مثل سطح المكتب، بمنزلقات وقوالب سهلة اللمس: ارفع من معرض صورك والمس قالبًا ونزّل الصورة المغيّرة الحجم.</p>\n<p>تتعامل متصفحات الهاتف جيدًا مع الأحجام المعتدلة، لكن اللوحات الكبيرة جدًا قد تستخدم ذاكرة كثيرة على جهاز محمول: البقاء بين 4000 و6000 بكسل يبقي المعالجة سلسة. واللصق يعمل على سطح المكتب بـCtrl+V، وعلى الهاتف يمكنك مشاركة لقطة شاشة إلى المتصفح أو اختيارها من المعرض: في كلتا الحالتين، تُعالج الصورة محليًا على الهاتف، فلا تُرفع أبدًا.</p>\n<h2 id=\"resize-for-social-media\">غيّر الحجم للتواصل الاجتماعي</h2>\n<p>المنصات الاجتماعية تقص بشكل لا يمكن التنبؤ به عندما تصل صورة بالحجم الخطأ، فتغيير الحجم قبل النشر يستحق الدقيقة التي يستغرقها: منشور مربع مغيّر الحجم إلى 1080 في 1080 يُعرض كما قصدت، بينما صورة عشوائية الحجم قد تُقص عند حافة مهمة.</p>\n<p>أبقِ الموضوع في الوسط وبعيدًا عن الحواف: تضع المنصات أزرارًا وتسميات وصور ملف شخصي فوق صورتك، وأي شيء قرب حافة قد يُخفى. وقالب لكل منصة يضع أبعادك في المكان الصحيح دون تخمين. وغيّر حجم نسخة لكل منصة بدل إعادة استخدام حجم في كل مكان: مصغرة يوتيوب 1280 في 720 وترويسة X 1500 في 500 لهما شكلان مختلفان، وحجم واحد لا يناسب الاثنين.</p>\n<p>وإذا يجب أن تذهب نفس الصورة إلى منصات عدة، غيّر الحجم من الأصل في كل مرة: تغيير حجم نسخة مغيّرة الحجم يراكم النعومة، بينما البدء من جديد من الأصل يحافظ على حدة كل نسخة.</p>\n<h2 id=\"resize-for-a-website\">غيّر الحجم لموقع ويب</h2>\n<p>يجب أن تطابق صور الويب حجم عرضها.</p>\n<p>صورة تُعرض بعرض 800 بكسل لا تحتاج 4000 بكسل في الملف، والبكسلات الإضافية تبطئ الصفحة فقط: غيّر الحجم إلى عرض العرض، مع قليل إضافي للشاشات الحادة. وصور مدونة بعرض 1200 بكسل قيمة افتراضية جيدة، لأنها تبدو حادة على سطح المكتب وتبقى خفيفة لقراء الهاتف.</p>\n<p>الصور الرئيسية قد تصل إلى 1920 عرضًا، بينما المصغرات والصور الرمزية قد تنزل إلى 600 أو أقل: اضبط كل صورة على فجوتها في الصفحة. واجمع تغيير الحجم مع تغيير صيغة لأفضل نتيجة.</p>\n<p>WebP بجودة 80 بالمئة إلى 85 بالمئة غالبًا أصغر ملف ما زال يبدو نظيفًا، ويستطيع مغيّر الحجم التحويل أثناء القياس. وللصورة الكاملة لسرعة الصفحة، راجع <a href=\"/ar/blog/taghyir-al-hajm-vs-daght-as-sura/\">تغيير الحجم أم ضغط الصورة: ما الفرق؟</a></p>\n<p>بعد تغيير الحجم، راجع حجم الملف إضافة إلى الأبعاد.</p>\n<p>JPG 1200 بكسل بجودة 85 بالمئة غالبًا له وزن معقول لصفحة ويب، بينما نفس الصورة محفوظة كـPNG قد تكون أثقل عدة مرات: إذا كان الملف ما زال ثقيلًا، اخفض الجودة قليلًا أو بدّل إلى WebP.</p>\n<h2 id=\"resize-for-print\">غيّر الحجم للطباعة</h2>\n<p>تحتاج الطباعة بكسلات أكثر من الشاشة، لأن الطابعة تركزها بكثافة: طباعة 6 في 4 بوصات عند 300 نقطة في البوصة تحتاج 1800 في 1200 بكسل، وطباعة أكبر تحتاج أكثر.</p>\n<p>أبقِ الجودة بين 95 بالمئة و100 بالمئة للطباعة، وفضّل PNG أو JPG عالي الجودة كمخرج: سيكون الملف أكبر من نسخة ويب، لكن هذا صحيح: الطباعة تُظهر كل عيب. ولا تكبّر أبدًا صورة صغيرة لتلبية حجم طباعة وتتوقع أن تبدو حادة: صورة 800 بكسل ممدودة إلى 1800 بكسل للطباعة ستبدو ناعمة على الورق، لأن البكسلات الجديدة مخترعة لا حقيقية.</p>\n<h2 id=\"troubleshooting\">حل المشاكل الشائعة</h2>\n<p>إذا بدت الصورة المغيّرة الحجم ممدودة، فكانت نسبة العرض إلى الارتفاع غير مقفلة مع تمديد دقيق، أو كُتب العرض والارتفاع منفصلين: أعد تغيير الحجم مع القفل مفعّلًا وسيبقى الشكل طبيعيًا.</p>\n<p>وإذا بدت الصورة المغيّرة الحجم ضبابية، فالسبب المعتاد تكبير أصل صغير أو تثبيت جودة منخفضة جدًا: راجع أبعاد الأصل أولًا: إذا كان المصدر أصغر من الهدف، فالتكبير هو المشكلة. وإذا خرج الملف أكبر بدل أصغر، فالصيغة هي السبب المحتمل: تحويل JPG إلى PNG أثناء تغيير الحجم ينتج ملفًا دون فقدان قد يزن أكثر من JPEG الأصلي.</p>\n<p>وإذا فقد GIF حركته، فهذا متوقع: ترسم اللوحة الإطار الأول لـGIF عند تغيير الحجم وتصدّر صورة ثابتة واحدة. وللحفاظ على حركة وتقليل وزنها، استخدم أداة ضغط GIF المخصصة بدل مغيّر الحجم.</p>\n<h2 id=\"quick-checklist\">قائمة تحقق سريعة</h2>\n<p>اعرف الحجم المستهدف وأبقِ النسبة مقفلة واختر الصيغة والجودة وراجع عرض المقارنة ونزّل: تلك هي العملية كلها، وتعمل بالتساوي لصورة واحدة أو لدفعة.</p>\n<p>جرّبه الآن في <a href=\"/ar/taghyir-hajm-as-suwar/\">مغيّر حجم الصور</a>. وللمفاهيم وراء كل ضبط، اقرأ <a href=\"/ar/blog/dalil-taghyir-hajm-as-suwar/\">دليل مغيّر حجم الصور الكامل</a>، ولمجلدات كاملة اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-hajm-suwar-mutaaddida/\">كيف تغيّر حجم صور متعددة دفعة واحدة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أغيّر حجم صورة إلى حجم دقيق، مثل 800 في 600؟","answer":"افتح مغيّر حجم الصور وارفع صورتك واختر وضع بالبكسلات: اكتب 800 في مربع العرض و600 في مربع الارتفاع، وأبقِ نسبة العرض إلى الارتفاع مقفلة إذا كانت الصورة لها ذلك الشكل أصلًا، أو افتحها واختر تغطية لفرض الإطار."},{"question":"كيف أصغّر صورة دون قص أي شيء؟","answer":"استخدم وضع بالنسبة المئوية واختر قيمة أقل من 100 بالمئة، مثل 50 بالمئة، مع قفل نسبة العرض إلى الارتفاع: تتقلص الصورة كلها متناسبة ولا يُقص شيء. وخيار آخر هو بالبكسلات بعرض أصغر ونسبة مقفلة."},{"question":"هل يمكنني تغيير حجم لقطة شاشة التقطتها للتو؟","answer":"نعم، انسخ اللقطة إلى الحافظة ثم اضغط Ctrl+V وأنت في صفحة مغيّر الحجم لإسقاطها مباشرة في القائمة: تحمل أبعادها فورًا وتُغيّر حجمها بضبطك الحالي دون حفظ ملف."},{"question":"ما أفضل حجم لمنشور إنستغرام؟","answer":"منشور إنستغرام المربع 1080 في 1080 بكسل: انقر قالب منشور إنستغرام في مغيّر الحجم فيملأ تلك الأبعاد لك. وإذا لم تكن صورتك مربعة، قصها بـقاص الصور إلى مربع أولًا."},{"question":"لماذا تبدو صورتي المغيّرة الحجم ضبابية؟","answer":"الضبابية غالبًا تأتي من تكبير أصل صغير، لأن الأداة يجب أن تمدد البكسلات الموجودة لملء الحجم الأكبر. ويمكن أن تأتي أيضًا من جودة منخفضة جدًا: راجع أبعاد الأصل وارفع الجودة إلى 85 بالمئة أو أعلى."},{"question":"هل يمكنني تغيير حجم نفس الصورة إلى أحجام مختلفة عدة؟","answer":"نعم، غيّر الحجم من الملف الأصلي في كل مرة، بدل تغيير حجم نسخة مغيّرة الحجم، ليبقى كل إصدار حادًا كما تسمح به المصدر. وارفع الأصل وثبّت الحجم الأول ونزّل، ثم كرر للحجم التالي."}];
